@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

/* ---------------------------------------------------------------------------
   Tokens. Dark is the default and the primary design; light is its own
   design, not an inversion. Near-black over pure black, paper over pure
   white. See DESIGN.md §6.
--------------------------------------------------------------------------- */

:root {
  color-scheme: light;

  --background: oklch(0.9895 0.0015 265);
  --surface: oklch(0.972 0.0025 265);
  --foreground: oklch(0.205 0.005 265);
  --muted: oklch(0.472 0.006 265);
  --dim: oklch(0.578 0.006 265);
  --border: oklch(0.205 0.005 265 / 0.13);
  --border-strong: oklch(0.205 0.005 265 / 0.26);
  --accent: oklch(0.53 0.155 248);
  --accent-quiet: oklch(0.53 0.155 248 / 0.14);

  /* Heatmap ramp — intensity darkens the paper. */
  --l0: oklch(0.205 0.005 265 / 0.055);
  --l1: oklch(0.62 0.07 248);
  --l2: oklch(0.56 0.11 248);
  --l3: oklch(0.49 0.14 248);
  --l4: oklch(0.41 0.16 250);
}

.dark {
  color-scheme: dark;

  --background: oklch(0.1615 0.004 265);
  --surface: oklch(0.202 0.005 265);
  --foreground: oklch(0.968 0.001 265);
  --muted: oklch(0.712 0.006 265);
  --dim: oklch(0.582 0.007 265);
  --border: oklch(1 0 0 / 0.1);
  --border-strong: oklch(1 0 0 / 0.2);
  --accent: oklch(0.735 0.135 244);
  --accent-quiet: oklch(0.735 0.135 244 / 0.18);

  --l0: oklch(1 0 0 / 0.055);
  --l1: oklch(0.36 0.055 248);
  --l2: oklch(0.5 0.09 246);
  --l3: oklch(0.62 0.12 245);
  --l4: oklch(0.755 0.14 244);
}

@theme inline {
  --color-background: var(--background);
  --color-surface: var(--surface);
  --color-foreground: var(--foreground);
  --color-muted: var(--muted);
  --color-dim: var(--dim);
  --color-border: var(--border);
  --color-border-strong: var(--border-strong);
  --color-accent: var(--accent);
  --color-accent-quiet: var(--accent-quiet);

  --font-sans: var(--font-geist-sans), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-geist-mono), ui-monospace, SFMono-Regular, monospace;

  --ease-out-quint: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-io: cubic-bezier(0.65, 0, 0.35, 1);
}

/* Six sizes. There is no seventh. */
@theme {
  --text-2xs: 0.6875rem; /* 11 — legend, month labels */
  --text-2xs--line-height: 1.4;
  --text-xs: 0.75rem; /* 12 — labels, metadata, nav */
  --text-xs--line-height: 1.45;
  --text-sm: 0.8125rem; /* 13 — descriptions, code */
  --text-sm--line-height: 1.6;
  --text-base: 0.9375rem; /* 15 — body, prose */
  --text-base--line-height: 1.72;
  --text-lg: 1.0625rem; /* 17 — names, row titles */
  --text-lg--line-height: 1.4;
  --text-2xl: 1.5rem; /* 24 — page + post titles */
  --text-2xl--line-height: 1.25;
}

/* ---------------------------------------------------------------------------
   Base
--------------------------------------------------------------------------- */

@layer base {
  * {
    border-color: var(--border);
  }

  html {
    -webkit-text-size-adjust: 100%;
    font-variant-numeric: tabular-nums;
    scroll-behavior: smooth;
    scroll-padding-top: 6rem;
  }

  body {
    background-color: var(--background);
    color: var(--foreground);
    font-family: var(--font-sans);
    font-size: var(--text-base);
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
    transition:
      background-color 250ms var(--ease-io),
      color 250ms var(--ease-io);
  }

  /* Suppress every transition until after first paint so the stored theme
     never animates in from the wrong colour. */
  .preload *,
  .preload *::before,
  .preload *::after {
    transition: none !important;
    animation: none !important;
  }

  ::selection {
    background: var(--accent-quiet);
    color: var(--foreground);
  }

  :focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
    border-radius: 2px;
  }

  ::-webkit-scrollbar {
    width: 11px;
    height: 11px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background: var(--border-strong);
    border: 3px solid var(--background);
    border-radius: 999px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: var(--dim);
  }
}

/* ---------------------------------------------------------------------------
   Chrome
--------------------------------------------------------------------------- */

.skip-link {
  position: fixed;
  top: 0.75rem;
  left: 50%;
  z-index: 90;
  translate: -50% -300%;
  padding: 0.5rem 0.875rem;
  border: 1px solid var(--border-strong);
  border-radius: 999px;
  background: var(--surface);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  transition: translate 200ms var(--ease-out-quint);
}
.skip-link:focus-visible {
  translate: -50% 0;
}

.section-label {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--dim);
}

/* Link with a hairline that thickens rather than appearing. Zero layout
   shift, which underline-on-hover cannot promise. */
.link-quiet {
  text-decoration: underline;
  text-decoration-color: var(--border-strong);
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  transition:
    color 150ms var(--ease-out-quint),
    text-decoration-color 150ms var(--ease-out-quint);
}
.link-quiet:hover {
  color: var(--foreground);
  text-decoration-color: var(--accent);
}

/* ---------------------------------------------------------------------------
   Entrance. Rules draw, text settles. Nothing bounces, nothing loops.
--------------------------------------------------------------------------- */

@keyframes rule-draw {
  from {
    transform: scaleX(0);
  }
  to {
    transform: scaleX(1);
  }
}

@keyframes settle {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes cell-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.reveal > * {
  animation: settle 380ms var(--ease-out-quint) both;
  animation-delay: calc(var(--i, 0) * 55ms + var(--base-delay, 0ms));
}

.rule {
  height: 1px;
  background: var(--border);
  transform-origin: left;
  animation: rule-draw 420ms var(--ease-out-quint) both;
  animation-delay: var(--base-delay, 0ms);
}

/* ---------------------------------------------------------------------------
   Masthead avatar slot — a designed absence (DESIGN.md §3). The footprint,
   the border, and the cursor-tracking light are all real; only the portrait
   is missing. Setting site.avatar swaps it in with no layout shift.
--------------------------------------------------------------------------- */

.avatar-slot {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 999px;
  border: 1px solid var(--border-strong);
  background: var(--surface);
}

.avatar-slot::before {
  content: "";
  position: absolute;
  inset: -40%;
  z-index: 1;
  background: radial-gradient(
    42% 42% at var(--lx, 50%) var(--ly, 50%),
    var(--accent-quiet),
    transparent 70%
  );
  opacity: var(--lit, 0);
  transition: opacity 320ms var(--ease-out-quint);
}

/* The grid of dots reads as "an image belongs here", not "an image failed". */
.avatar-slot::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  background-image: radial-gradient(
    currentColor 0.5px,
    transparent 0.5px
  );
  background-size: 4px 4px;
  color: var(--dim);
  opacity: 0.42;
}

/* ---------------------------------------------------------------------------
   Activity grid
--------------------------------------------------------------------------- */

.activity-grid {
  --cell-gap: 3px;
  display: grid;
  grid-auto-flow: column;
  grid-template-rows: repeat(7, 1fr);
  gap: var(--cell-gap);
  width: 100%;
}

.activity-cell {
  aspect-ratio: 1;
  border-radius: 2px;
  background: var(--level, var(--l0));
  position: relative;
  animation: cell-in 260ms var(--ease-out-quint) both;
  animation-delay: calc(var(--col, 0) * 5ms + 320ms);
  transition: outline-color 120ms var(--ease-out-quint);
  outline: 1px solid transparent;
  outline-offset: 1px;
}

.activity-cell[data-active="true"] {
  outline-color: var(--foreground);
}

.activity-cell[data-live="true"]::after {
  content: "";
  position: absolute;
  inset: -2px;
  border-radius: 3px;
  border: 1px solid var(--accent);
}

/* Every cell keeps a ≥24px target even at 8px of paint. */
.activity-cell button,
.activity-cell::before {
  content: "";
  position: absolute;
  inset: -50%;
  min-width: 24px;
  min-height: 24px;
}

/* ---------------------------------------------------------------------------
   Rows
--------------------------------------------------------------------------- */

.row-item {
  position: relative;
  display: block;
  padding: 1.125rem 0.75rem;
  margin-inline: -0.75rem;
  border-radius: 6px;
  transition: background-color 160ms var(--ease-out-quint);
}
.row-item:hover {
  background: color-mix(in oklab, var(--surface) 72%, transparent);
}

.row-dest {
  opacity: 0;
  transform: translateY(2px);
  transition:
    opacity 160ms var(--ease-out-quint),
    transform 160ms var(--ease-out-quint);
}
.row-item:hover .row-dest,
.row-item:focus-visible .row-dest {
  opacity: 1;
  transform: none;
}
.row-item:hover .row-year,
.row-item:focus-visible .row-year {
  opacity: 0;
}
.row-year {
  transition: opacity 160ms var(--ease-out-quint);
}

/* ---------------------------------------------------------------------------
   Prose (MDX)
--------------------------------------------------------------------------- */

.prose {
  color: var(--foreground);
  font-size: var(--text-base);
}
.prose > * + * {
  margin-top: 1.35em;
}
.prose h2,
.prose h3 {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  font-weight: 500;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--dim);
  margin-top: 3rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border);
}
.prose h2 + *,
.prose h3 + * {
  margin-top: 1rem;
}
.prose a {
  color: var(--foreground);
  text-decoration: underline;
  text-decoration-color: var(--border-strong);
  text-underline-offset: 3px;
  transition: text-decoration-color 150ms var(--ease-out-quint);
}
.prose a:hover {
  text-decoration-color: var(--accent);
}
.prose strong {
  font-weight: 550;
}
.prose ul,
.prose ol {
  padding-left: 1.25rem;
}
.prose ul {
  list-style: disc;
}
.prose ol {
  list-style: decimal;
}
.prose li::marker {
  color: var(--dim);
}
.prose li + li {
  margin-top: 0.5rem;
}
.prose blockquote {
  padding-left: 1.125rem;
  border-left: 1px solid var(--accent);
  color: var(--muted);
}
.prose hr {
  border: 0;
  border-top: 1px solid var(--border);
}
.prose img {
  border-radius: 8px;
  border: 1px solid var(--border);
}
.prose :not(pre) > code {
  font-family: var(--font-mono);
  font-size: 0.9em;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 0.1em 0.35em;
}
.prose pre {
  font-family: var(--font-mono);
  font-size: var(--text-sm);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1rem 1.125rem;
  overflow-x: auto;
}
.prose pre code {
  background: none;
  border: 0;
  padding: 0;
}
.prose .anchor {
  position: absolute;
}

/* sugar-high — four roles, no rainbow */
.prose pre .sh__token--keyword,
.prose pre .sh__token--sign {
  color: var(--accent);
}
.prose pre .sh__token--string,
.prose pre .sh__token--property {
  color: var(--muted);
}
.prose pre .sh__token--comment {
  color: var(--dim);
}
.prose pre .sh__token--identifier,
.prose pre .sh__token--entity {
  color: var(--foreground);
}

/* ---------------------------------------------------------------------------
   Command palette
--------------------------------------------------------------------------- */

@keyframes palette-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.palette-panel {
  animation: palette-in 200ms var(--ease-out-quint) both;
}

.palette-backdrop {
  animation: cell-in 160ms linear both;
  background: color-mix(in oklab, var(--background) 62%, transparent);
  backdrop-filter: blur(6px);
}

/* ---------------------------------------------------------------------------
   Reduced motion: movement goes, colour feedback stays.
--------------------------------------------------------------------------- */

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-delay: 0ms !important;
    animation-iteration-count: 1 !important;
  }
  .reveal > *,
  .rule,
  .activity-cell,
  .palette-panel {
    animation: none !important;
    opacity: 1;
    transform: none;
  }
  .row-dest {
    transition: opacity 120ms linear;
  }
}

export type ColorScheme = "light" | "dark";
export type ThemeOverride = ColorScheme | null;

/**
 * Dark is the default and the primary design; light is a real alternative,
 * not an inversion (DESIGN.md §6). A manual choice always wins and is
 * persisted. Runtime applies this via `next-themes`; this is the contract.
 */
export const DEFAULT_THEME: ColorScheme = "dark";

export function resolveTheme(override: ThemeOverride): ColorScheme {
  return override ?? DEFAULT_THEME;
}

export function nextTheme(current: ColorScheme): ColorScheme {
  return current === "dark" ? "light" : "dark";
}

import { expect, test } from "bun:test";
import { DEFAULT_THEME, nextTheme, resolveTheme } from "@/lib/theme";

test("dark is the default when no override is stored", () => {
  expect(resolveTheme(null)).toBe("dark");
  expect(DEFAULT_THEME).toBe("dark");
});

test("a manual override always wins", () => {
  expect(resolveTheme("light")).toBe("light");
  expect(resolveTheme("dark")).toBe("dark");
});

test("toggling alternates between exactly two schemes", () => {
  expect(nextTheme("dark")).toBe("light");
  expect(nextTheme("light")).toBe("dark");
  expect(nextTheme(nextTheme("dark"))).toBe("dark");
});

import type { SVGProps } from "react";

