7	
8	export type DailyTokens = {
9	  date: string;
10	  tokens: number;
11	};
12	
13	export type Intensity = 0 | 1 | 2 | 3 | 4;
14	
15	export type ActivityDay = DailyTokens & {
16	  intensity: Intensity;
17	  /** Synthetic “live” projection for the current local day. */
18	  live?: boolean;
19	};
20	
21	export type AiActivity = {
22	  days: ActivityDay[];
23	  lifetimeTokens: number;
24	  /** ISO timestamp of the nightly payload, when known. */
25	  generatedAt: string | null;
26	  timezone: string;
27	};
28	
29	export type AiActivitySource = "blob" | "fallback";
30	
31	/** GitHub-like 5-level scale relative to the densest day in the series. */
32	export function intensityFromTokens(
33	  tokens: number,
34	  maxTokens: number,
35	): Intensity {
36	  if (tokens <= 0 || maxTokens <= 0) return 0;
37	  const ratio = tokens / maxTokens;
38	  if (ratio <= 0.25) return 1;
39	  if (ratio <= 0.5) return 2;
40	  if (ratio <= 0.75) return 3;
41	  return 4;
42	}
43	
44	/**
45	 * Expand a sparse daily series into consecutive calendar days (0-filled gaps)
46	 * ending on `endDate`, keeping at most `windowDays` cells.
47	 */
48	export function fillSparseDailySeries(
49	  days: readonly DailyTokens[],
50	  endDate: string,
51	  windowDays = 365,
52	): DailyTokens[] {
53	  const byDate = new Map(days.map((d) => [d.date, d.tokens]));
54	  const startDate = shiftYmd(endDate, -(windowDays - 1));
55	  const filled: DailyTokens[] = [];
56	  for (
57	    let cursor = startDate;
58	    cursor <= endDate;
59	    cursor = shiftYmd(cursor, 1)
60	  ) {
61	    filled.push({ date: cursor, tokens: byDate.get(cursor) ?? 0 });
62	  }
63	  return filled;
64	}
65	
66	export function buildAiActivity(
67	  series: readonly DailyTokens[],
68	  options?: {
69	    liveDate?: string;
70	    generatedAt?: string | null;
71	    timezone?: string;
72	    /** Authoritative lifetime from the payload (preferred over series sum). */
73	    lifetimeTokens?: number;
74	  },
75	): AiActivity {
76	  const max = Math.max(0, ...series.map((d) => d.tokens));
77	  const liveDate = options?.liveDate;
78	
79	  const days: ActivityDay[] = series.map((day) => ({
80	    ...day,
81	    intensity: intensityFromTokens(day.tokens, max),
82	    live: liveDate === day.date ? true : undefined,
83	  }));
84	
85	  const seriesSum = series.reduce((sum, day) => sum + day.tokens, 0);
86	  const lifetimeTokens =
87	    options?.lifetimeTokens !== undefined
88	      ? options.lifetimeTokens
89	      : seriesSum;
90	
91	  return {
92	    days,
93	    lifetimeTokens,
94	    generatedAt: options?.generatedAt ?? null,
95	    timezone: options?.timezone ?? AI_ACTIVITY_TIMEZONE,
96	  };
97	}
98	
99	/**
100	 * Fraction of the local calendar day elapsed [0, 1].
101	 */
102	export function dayFractionElapsed(now: Date, timeZone: string): number {
103	  const parts = new Intl.DateTimeFormat("en-US", {
104	    timeZone,
105	    hour: "numeric",
106	    minute: "numeric",
107	    second: "numeric",
108	    hourCycle: "h23",
109	  }).formatToParts(now);
110	  const hour = Number(parts.find((p) => p.type === "hour")?.value ?? 0);
111	  const minute = Number(parts.find((p) => p.type === "minute")?.value ?? 0);
112	  const second = Number(parts.find((p) => p.type === "second")?.value ?? 0);
113	  const elapsed = hour * 3600 + minute * 60 + second;
114	  return Math.min(1, Math.max(0, elapsed / 86_400));
115	}
116	
117	/**
118	 * Conservative full-day baseline: minimum of the last up-to-7 days
119	 * before `beforeDate` that have tokens > 0.
120	 */
121	export function sevenDayMinBaseline(
122	  days: readonly { date: string; tokens: number }[],
123	  beforeDate: string,
124	): number {
125	  const prior = days
126	    .filter((d) => d.date < beforeDate && d.tokens > 0)
127	    .sort((a, b) => a.date.localeCompare(b.date))
128	    .slice(-7);
129	  if (prior.length === 0) return 0;
130	  return Math.min(...prior.map((d) => d.tokens));
131	}
132	
133	/** Projected tokens “so far today” from the 7-day min baseline. */
134	export function projectTodayTokens(
135	  days: readonly { date: string; tokens: number }[],
136	  now: Date,
137	  timeZone: string,
138	): { date: string; tokens: number; baseline: number } {
139	  const today = calendarDateInTimeZone(now, timeZone);
140	  const baseline = sevenDayMinBaseline(days, today);
141	  const tokens = Math.round(baseline * dayFractionElapsed(now, timeZone));
142	  return { date: today, tokens, baseline };
143	}
144	
145	/** Cacheable history through the payload’s last published day (no live today). */
146	export function materializeHistory(payload: AiActivityPayload): AiActivity {
147	  const timeZone = payload.timezone || AI_ACTIVITY_TIMEZONE;
148	  const history = [...payload.days].sort((a, b) =>
149	    a.date.localeCompare(b.date),
150	  );
151	  const endHistory = history.at(-1)!.date;
152	
153	  return buildAiActivity(fillSparseDailySeries(history, endHistory, 364), {
154	    generatedAt: payload.generatedAt,
155	    timezone: timeZone,
156	    lifetimeTokens: payload.lifetimeTokens,
157	  });
158	}
159	
160	/**
161	 * Append the live today cell. Projection is ≤ recent positive days, so
162	 * existing intensities stay valid without a full rebuild.
163	 * Lifetime stays the published nightly total (excludes synthetic today).
164	 */
165	export function withLiveToday(history: AiActivity, now = new Date()): AiActivity {
166	  const projection = projectTodayTokens(
167	    history.days,
168	    now,
169	    history.timezone,
170	  );
171	  // Avoid duplicating the last published day if clocks briefly disagree.
172	  if (projection.date <= (history.days.at(-1)?.date ?? "")) {
173	    return history;
174	  }
175	  const max = Math.max(0, ...history.days.map((d) => d.tokens));
176	
177	  return {
178	    days: [
179	      ...history.days,
180	      {
181	        date: projection.date,
182	        tokens: projection.tokens,
183	        intensity: intensityFromTokens(projection.tokens, max),
184	        live: true,
185	      },
186	    ],
187	    lifetimeTokens: history.lifetimeTokens,
188	    generatedAt: history.generatedAt,
189	    timezone: history.timezone,
190	  };
191	}
192	
193	export function materializeAiActivity(
194	  payload: AiActivityPayload,
195	  now = new Date(),
196	  options?: { includeLiveToday?: boolean },
197	): AiActivity {
198	  const history = materializeHistory(payload);
199	  if (options?.includeLiveToday === false) return history;
200	  return withLiveToday(history, now);
201	}
202	
203	export function formatTokenCount(tokens: number): string {
204	  return new Intl.NumberFormat("en-US").format(tokens);
205	}
206	
207	export const LIVE_COUNT_START_RATIO = 0.8;
208	export const LIVE_COUNT_DURATION_MS = 90_000;
